# 어텐션과 MLP 의 산술 강도 — 강의의 식을 숫자로 (bf16)
def mlp(B, T, D, F):
    return 6*B*T*D*F / (4*B*T*D + 4*B*T*F + 6*D*F)
def attn(B, S, T, D):
    return 4*B*S*T*D / (4*B*S*D + 4*B*T*D)

D, F, S = 4096, 14336, 4096
for name, T in [("prefill", S), ("decode", 1)]:
    for B in [1, 64]:
        print(f"{name:7s} B={B:3d}  MLP={mlp(B,T,D,F):8.1f}  attention={attn(B,S,T,D):7.1f}")
